function getListingById(id) {
  return OUTLANDIS_LISTINGS.catalog.find(l => l.id === id || l.slug === id);
}

function getListingBySlug(slug) {
  return OUTLANDIS_LISTINGS.catalog.find(l => l.slug === slug);
}
